class Ledger:
 def __init__(self): self.balance=0; self.seen=set()
 def apply(self,txid,amount):
  if txid in self.seen: raise ValueError('duplicate')
  self.seen.add(txid)
  if not isinstance(amount,int) or isinstance(amount,bool): raise TypeError('amount')
  if self.balance+amount<0: raise ValueError('overdraft')
  self.balance+=amount
  return self.balance

